import{z as i,x as m,o,c as p,q as d,j as l,D as e,d as t,s,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"循环 Transformer","description":"","frontmatter":{"title":"循环 Transformer","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/looped-transformer.md","filePath":"llm/looped-transformer.md","lastUpdated":1791063341000}'),A={name:"llm/looped-transformer.md"};function B(T,a,f,u,h,D){const n=m("Mermaid");return o(),p("div",null,[a[2]||(a[2]=d('<h1 id="循环-transformer" tabindex="-1">循环 Transformer <a class="header-anchor" href="#循环-transformer" aria-label="Permalink to &quot;循环 Transformer&quot;">​</a></h1><div class="epigraph"><p>把同一 Transformer 块循环足够多次，可以模拟可编程的迭代算法；循环次数是测试时的计算旋钮。</p><footer>—— Giannou et al., Looped Transformers as Programmable Computers, ICML 2023</footer></div><p><a href="/llm/universal-transformer-recurrence">上一课</a>带 ACT 的共享块，停机门把课序弄复杂。现代工作常去掉自适应，改成<strong>固定或测试时选择的循环次数 \\(T\\)</strong>：训练用中等 \\(T\\)，推理对难题加大 \\(T\\)。这就是 looped Transformer。它接 Universal 的参数共享，但把计算预算从每位置门收到一个全局整数。下一课早退会把预算再按层或按 token 切开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ACT 的停机门难训，批内不同步。需要一种更硬的陈述：若 \\(F_\\theta\\) 足够表达，则 \\(F_\\theta^{\\circ T}\\) 可以模拟多步算法（复制、计数、简单程序），\\(T\\) 增大等于多给计算，而不改参数。缺口是把这件事写成与权重解耦的<strong>测试时计算</strong>，并标明它与「加不共享的层」在泛化上的差别。</p><p><span class="marginnote">直觉类比：加不共享的深度像换更多把不同的尺子，每把只会一种量法；循环是把同一把尺子反复量 \\(T\\) 次——参数（刻度）不变，多做几遍原来一遍做不完的事。两者的参数账和泛化行为要分开算。</span></p><p>Giannou 等人给出构造性结果：在理想化设定下，looped Transformer 可模拟计算机。后续经验工作用循环块做算术、长度外推、推理链。本课取机制，不把某篇竞赛级算术论文展开成词条。</p><p><span class="marginnote">循环次数 \\(T\\) 不是序列长度 \\(n\\)。\\(n\\) 仍由注意力二次项决定。\\(T\\) 决定块应用多少次。长上下文与多步思考不是同一轴，尽管都贵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选 \\(k\\) 层作为一个循环体（\\(k=1\\) 最干净），前面可留若干不共享的 prelude 层写表示，后面可留 coda 层读结果。中间对循环体应用 \\(T\\) 次，每次都带残差与归一化。训练对 \\(T\\sim T_{\\mathrm{train}}\\) 或对 \\(T\\) 做随机抽样，使模型习惯不同迭代深度。推理设 \\(T_{\\mathrm{test}}\\ge T_{\\mathrm{train}}\\)，观察是否还能改进——这是「算力换准确」是否成立的检验。</p><p>输入可以每步重新注入（像 RNN 读 \\(x_t\\)，但这里 \\(x\\) 是整段），也可以只在 \\(t=0\\) 注入。重新注入有助于避免状态遗忘任务条件；只注入一次则更像对隐状态做独立迭代。</p><h3 id="与加层的参数账" tabindex="-1">与加层的参数账 <a class="header-anchor" href="#与加层的参数账" aria-label="Permalink to &quot;与加层的参数账&quot;">​</a></h3><p>\\(L=kT\\) 的不共享模型参数约 \\(T\\) 倍于循环体。循环模型用一份参数换 \\(T\\) 次计算。若任务真是同一规则迭代，循环更参数高效；若每层需要不同规则，循环会欠拟合，必须加大 \\(k\\) 或放弃共享。</p><p><span class="marginnote">数字实例：设循环体 \\(k=2\\) 层。要等效深度 \\(L=24\\)，不共享模型需要 24 份层参数；循环模型只存 2 份、跑 \\(T=12\\) 轮，参数省 12 倍，但每个 token 的前向计算量仍是 24 层那么多——省的是显存里的权重，不是算力。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每次循环，注意力看见的是上一轮混合后的整段状态，因此可以多步传播信息：第一步把局部证据写入某些位置，第二步远端查询再读这些位置。这与加深不共享模型类似，但强制每步用同一套路由参数，电路必须可复用。不能复用时，增大 \\(T\\) 会振荡或饱和，而不是单调变好——这是诊断：若 \\(T_{\\mathrm{test}}\\) 加大立刻变差，说明训练没覆盖该预算，或任务根本不是迭代算法。</p>',16)),(o(),l(E,null,{default:e(()=>[s(n,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20R1%5B%22%E7%AC%AC%201%20%E8%BD%AE%EF%BC%9A%E5%B1%80%E9%83%A8%E8%AF%81%E6%8D%AE%E5%86%99%E5%85%A5%E4%BD%8D%E7%BD%AE%20p%22%5D%20--%3E%20ST%5B%22%E6%B7%B7%E5%90%88%E5%90%8E%E7%9A%84%E6%95%B4%E6%AE%B5%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST%20--%3E%20R2%5B%22%E7%AC%AC%202%20%E8%BD%AE%EF%BC%9A%E8%BF%9C%E7%AB%AF%E4%BD%8D%E7%BD%AE%E6%9D%A5%E6%9F%A5%E8%AF%A2%20p%22%5D%0A%20%20R2%20--%3E%20ST2%5B%22%E7%AC%AC%202%20%E8%BD%AE%E7%9A%84%E6%95%B4%E6%AE%B5%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST2%20--%3E%20R3%5B%22%E7%AC%AC%20T%20%E8%BD%AE%EF%BC%9A%E8%AF%81%E6%8D%AE%E5%B7%B2%E4%BC%A0%E6%92%AD%E5%88%B0%E6%89%80%E9%9C%80%E8%8C%83%E5%9B%B4%22%5D%0A%20%20R1%20-.-%3E%7C%22%E6%AF%8F%E4%B8%80%E8%BD%AE%E9%83%BD%E6%98%AF%E5%90%8C%E4%B8%80%E4%BB%BD%E5%8F%82%E6%95%B0%22%7C%20R2%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,[r("span",{class:"marginnote"},"常见误区：加大 \\(T_{\\mathrm{test}}\\) 反而变差时，初学者常以为是训练量不够，再多练就好。按原文逻辑这更是诊断信号——要么训练没覆盖该预算，要么任务本就不是能用同一规则迭代的东西，硬加轮数只会振荡或饱和。")],-1)),a[4]||(a[4]=r("p",null,"Prelude/coda 的存在承认「输入嵌入」和「输出解码」往往不应共享中间推理块的权重，这与 Universal Transformer 把一切塞进 \\(F_\\theta\\) 的极端设定不同。",-1)),a[5]||(a[5]=r("p",null,[r("span",{class:"marginnote"},"梯度穿过 \\(T\\) 次 \\(F_\\theta\\)，与激活检查点一起决定能否训大 \\(T\\)。实践中 \\(T_{\\mathrm{train}}\\) 往往小于希望的 \\(T_{\\mathrm{test}}\\)，外推计算步数并不自动成立。")],-1)),a[6]||(a[6]=r("h2",{id:"边界",tabindex:"-1"},[t("边界 "),r("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[7]||(a[7]=r("p",null,"Looped 不是免费的推理时思考。每加一循环就加一整段注意力 FLOPs，延迟线性涨。对语言建模困惑度，共享循环常常弱于同样 FLOPs 的不共享深层模型，因为语言模型不是整齐的迭代算法。本课的适用边界是算法化、可多步改进的任务，以及参数极度受限时。下一课早退把「不必跑满 \\(T\\)」从全局整数改回按例决策。",-1)),(o(),l(E,null,{default:e(()=>[s(n,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20In%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20P%5B%22Prelude%20%E4%B8%8D%E5%85%B1%E4%BA%AB%22%5D%0A%20%20P%20--%3E%20Loop%5B%22%E5%85%B1%E4%BA%AB%E5%9D%97%20x%20T%22%5D%0A%20%20Loop%20--%3E%20Loop%0A%20%20Loop%20--%3E%20C%5B%22Coda%20%E4%B8%8D%E5%85%B1%E4%BA%AB%22%5D%0A%20%20C%20--%3E%20Out%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r("h2",{id:"小结",tabindex:"-1"},[t("小结 "),r("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[9]||(a[9]=r("ul",null,[r("li",null,"Looped Transformer 用全局循环次数 \\(T\\) 当测试时计算旋钮，去掉 ACT 的每位置门。"),r("li",null,"同一规则的迭代任务上，参数远少于同等深度的不共享栈。"),r("li",null,"\\(T_{\\mathrm{test}}\\gt T_{\\mathrm{train}}\\) 不自动变好；振荡说明规则不可复用或预算没训到。"),r("li",null,"语言模型困惑度往往更吃不共享的深度。"),r("li",null,"出处：Giannou et al., ICML 2023。")],-1))])}const k=i(A,[["render",B]]);export{_ as __pageData,k as default};
